// Owner: staff menu images (task C). Staff-side routes for the printed menu slides (data/menu-images.json):
//   GET  /staff/menu-images                    slide index for the console (keys, titles, claim flags, groups)
//   GET  /staff/menu-images/:group/:n          JPEG thumbnail of one slide; only keys of the index are served, from the
//                                              bundle generated by scripts/build_menu_thumbs.py (no file system access)
//   POST /staff/conversations/:id/menu-images  "Gửi menu": staff queue the overview covers or a group's price slides
// Staff may include slides with has_medical_claim = true (the bot never sends them) only with include_claim_slides =
// true, which the console sets after a confirm dialog. The send writes one messages row (kind 'image', source 'staff')
// and one cs_images outbox row (src/bridge/outbox.ts queuePersonalImages); the bridge sends it with `msg send-image`.
// It does not change bot_state: the bot keeps answering, and the image label reaches the model as a sent message.
import type { Context } from 'hono';
import type { AppEnv, MessageView, SendMenuImagesResponse, StaffMenuImagesResponse, StaffMenuSlide } from '../types';
import { HttpError, readJson } from '../lib/http';
import { getFlags } from '../lib/flags';
import { getCustomer, mustConversation, safeJson } from '../lib/db';
import { auditStatement } from '../lib/audit';
import { newId } from '../lib/ids';
import { isPersonalUserId } from '../lib/zalo-personal';
import {
  MAX_MENU_IMAGES,
  MENU_GROUPS,
  MENU_INDEX,
  type MenuGroup,
  type MenuSlide,
  isMenuImageKey,
  menuAttachments,
  menuImagesLabel,
  menuSlide,
  slideKey,
} from '../lib/menu-images';
import { queuePersonalImages } from '../bridge/outbox';
import { MENU_THUMBS } from '../menu-thumbs';

type H = (c: Context<AppEnv>) => Promise<Response>;

const staffId = (c: Context<AppEnv>) => c.get('staffId') ?? 'staff';

function keysOf(group: MenuGroup, ns: number[]): string[] {
  return ns.map((n) => slideKey(group, n)).filter((k) => isMenuImageKey(k));
}

/** The slides a "Gửi menu" choice offers: the covers of every group ('overview') or one group's price slides. */
export function menuChoiceKeys(group: string): string[] | null {
  if (group === 'overview') return MENU_INDEX.overview_groups.flatMap((g) => keysOf(g, MENU_INDEX.groups[g].cover));
  if ((MENU_GROUPS as string[]).includes(group)) return keysOf(group as MenuGroup, MENU_INDEX.groups[group as MenuGroup].price_list);
  return null;
}

function slideView(s: MenuSlide): StaffMenuSlide {
  return {
    key: s.key,
    group: s.group,
    group_label: MENU_INDEX.groups[s.group].label,
    n: s.n,
    title: s.title,
    kind: s.kind,
    has_medical_claim: s.has_medical_claim,
    claim_note: s.claim_note,
    service_ids: s.service_ids,
    thumb: typeof MENU_THUMBS[s.key] === 'string',
  };
}

export const listMenuImages: H = async (c) => {
  const res: StaffMenuImagesResponse = {
    max_images: MAX_MENU_IMAGES,
    overview: menuChoiceKeys('overview') ?? [],
    groups: MENU_GROUPS.map((g) => {
      const def = MENU_INDEX.groups[g];
      return {
        group: g,
        label: def.label,
        catalog_group: def.catalog_group,
        cover: keysOf(g, def.cover),
        price_list: keysOf(g, def.price_list),
        review_note: def.review_note ?? null,
      };
    }),
    // Only slides a cover, a price list or a service points to; the internal customer form (hair-removal/3) is not one.
    slides: MENU_INDEX.slides.filter((s) => typeof MENU_THUMBS[s.key] === 'string').map(slideView),
  };
  return c.json(res);
};

function base64ToBytes(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export const menuThumb: H = async (c) => {
  const key = `${c.req.param('group')}/${c.req.param('n')}`;
  const b64 = isMenuImageKey(key) ? MENU_THUMBS[key] : undefined;
  if (typeof b64 !== 'string') throw new HttpError(404, 'not_found', 'no thumbnail for this menu image key');
  return new Response(base64ToBytes(b64), {
    status: 200,
    headers: {
      'content-type': 'image/jpeg',
      'cache-control': 'private, max-age=86400',
      'x-content-type-options': 'nosniff',
    },
  });
};

export const sendMenuImages: H = async (c) => {
  const id = c.req.param('id')!;
  const b = await readJson<{ group?: unknown; keys?: unknown; include_claim_slides?: unknown }>(c);
  if (typeof b?.group !== 'string') throw new HttpError(422, 'validation_failed', "group must be 'overview' or a menu group", { field: 'group' });
  const offered = menuChoiceKeys(b.group);
  if (!offered) throw new HttpError(422, 'validation_failed', `group must be one of overview, ${MENU_GROUPS.join(', ')}`, { field: 'group' });
  if (b.include_claim_slides !== undefined && typeof b.include_claim_slides !== 'boolean') {
    throw new HttpError(422, 'validation_failed', 'include_claim_slides must be a boolean', { field: 'include_claim_slides' });
  }
  let keys: string[];
  if (b.keys === undefined) {
    keys = offered.filter((k) => !menuSlide(k)!.has_medical_claim);
  } else {
    if (!Array.isArray(b.keys) || b.keys.some((k) => typeof k !== 'string')) throw new HttpError(422, 'validation_failed', 'keys must be an array of strings', { field: 'keys' });
    const outside = (b.keys as string[]).filter((k) => !offered.includes(k));
    if (outside.length) throw new HttpError(422, 'validation_failed', 'keys must be slides of the chosen group', { field: 'keys', unknown: outside.slice(0, 10) });
    keys = offered.filter((k) => (b.keys as string[]).includes(k)); // index order, de-duplicated
  }
  if (!keys.length) throw new HttpError(422, 'validation_failed', 'no menu image to send', { field: 'keys' });
  if (keys.length > MAX_MENU_IMAGES) throw new HttpError(422, 'validation_failed', `at most ${MAX_MENU_IMAGES} images per send`, { field: 'keys' });
  const claimKeys = keys.filter((k) => menuSlide(k)!.has_medical_claim);
  if (claimKeys.length && b.include_claim_slides !== true) {
    throw new HttpError(422, 'validation_failed', 'these slides print health claims; confirm with include_claim_slides: true', {
      field: 'include_claim_slides',
      claim_keys: claimKeys,
    });
  }

  const conv = await mustConversation(c.env, id);
  const customer = await getCustomer(c.env, conv.customer_id);
  if (!customer) throw new HttpError(404, 'not_found', 'customer not found');
  const flags = await getFlags(c.env);
  if (!flags.outbound_enabled) throw new HttpError(409, 'outbound_disabled', 'outbound_enabled is false');
  if (conv.bot_state === 'blocked') throw new HttpError(409, 'invalid_state', 'conversation is blocked');
  if (!isPersonalUserId(customer.zalo_user_id)) throw new HttpError(409, 'invalid_state', 'menu images are sent on the personal channel only');

  const db = c.env.DB;
  const now = Date.now();
  const sid = staffId(c);
  const msgId = newId('msg', now);
  await db
    .prepare(
      "INSERT INTO messages (id, conversation_id, direction, source, kind, text, attachments_json, staff_id, send_state, client_send_id, created_at, seq) VALUES (?,?,'outbound','staff','image',?,?,?,'pending',?,?,(SELECT COALESCE(MAX(seq), 0) + 1 FROM messages WHERE conversation_id = ?))",
    )
    .bind(msgId, conv.id, menuImagesLabel(keys), JSON.stringify(menuAttachments(keys)), sid, `img_${msgId}`, now, conv.id)
    .run();
  let q: { outbox_id: string; keys: string[] };
  try {
    q = await queuePersonalImages(
      c.env,
      { conversation_id: conv.id, customer_id: customer.id, zalo_user_id: customer.zalo_user_id, message_id: msgId, keys, depends_on: null, dedupe_key: `img:staff:${msgId}`, draft_id: null },
      now,
    );
  } catch (e) {
    await db.prepare("UPDATE messages SET send_state = 'failed', send_error = ? WHERE id = ?").bind(`not queued: ${(e as Error).message ?? 'error'}`.slice(0, 300), msgId).run();
    throw e;
  }
  await db.batch([
    db.prepare('UPDATE conversations SET last_message_at = ?, updated_at = ? WHERE id = ?').bind(now, now, conv.id),
    auditStatement(c.env, {
      actor_type: 'staff',
      actor_id: sid,
      action: 'message.menu_images',
      entity: 'conversation',
      entity_id: conv.id,
      after: { group: b.group, images: q.keys.length, claim_slides: claimKeys.length, outbox_id: q.outbox_id },
    }, now),
  ]);
  const m = await db.prepare('SELECT * FROM messages WHERE id = ?').bind(msgId).first<Record<string, unknown>>();
  const message: MessageView = {
    id: m!.id as string,
    direction: 'outbound',
    source: 'staff',
    kind: 'image',
    text: (m!.text as string | null) ?? null,
    attachments: safeJson(m!.attachments_json as string | null, []),
    send_state: m!.send_state as MessageView['send_state'],
    draft_id: null,
    staff_id: sid,
    created_at: m!.created_at as number,
    sent_at: (m!.sent_at as number | null) ?? null,
  };
  const res: SendMenuImagesResponse = { message, outbox_id: q.outbox_id, keys: q.keys };
  return c.json(res);
};
